const listVenueMenus = `-- name: ListVenueMenus :many
SELECT id, tenant_id, venue_id, name, status, published_at, created_at, updated_at FROM menus WHERE tenant_id = $1 AND venue_id = $2 ORDER BY created_at, id
`

type ListVenueMenusParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	VenueID  uuid.UUID `json:"venue_id"`
}

func (q *Queries) ListVenueMenus(ctx context.Context, arg ListVenueMenusParams) ([]Menu, error) {
	rows, err := q.db.Query(ctx, listVenueMenus, arg.TenantID, arg.VenueID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Menu{}
	for rows.Next() {
		var i Menu
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.VenueID,
			&i.Name,
			&i.Status,
			&i.PublishedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

